#!/usr/bin/env node
/**
 * Coverage Tier Validation Script
 *
 * Reads coverage/coverage-summary.json (generated by vitest --coverage)
 * and validates per-tier coverage targets defined in spec.md.
 *
 * Usage:
 *   node scripts/check-coverage-tiers.mjs           # check generated report
 *   COVERAGE_JSON=path node scripts/check-coverage-tiers.mjs  # custom path
 *
 * Exit codes:
 *   0 - All tiers pass
 *   1 - Some tiers below target
 *   2 - Coverage report not found
 */

import { readFileSync, existsSync } from "node:fs";
import { resolve, dirname } from "node:path";
import { fileURLToPath } from "node:url";

const HERE = dirname(fileURLToPath(import.meta.url));
const ROOT = resolve(HERE, "..");

// ── Tier configuration ─────────────────────────────────────────────────
// No modules are exempted from coverage gates: repositories, quiz orchestration,
// and all remaining source files are covered by real tests.
const INTENTIONALLY_MOCKED = [];

const TIERS = [
  {
    name: "Tier 1: Core domain logic",
    target: 90,
    metric: "statements",
    patterns: [/\/lib\/shuffle\.ts$/, /\/lib\/choice-label\.ts$/, /\/lib\/date\.ts$/],
  },
  {
    name: "Tier 2: API orchestration",
    target: 80,
    metric: "statements",
    patterns: [/\/app\/api\/.+\.ts$/],
  },
  {
    name: "Tier 2b: API client & utilities",
    target: 85,
    metric: "statements",
    patterns: [/\/lib\/api\/.+\.ts$/],
  },
  {
    name: "Tier 3: Data access",
    target: 75,
    metric: "statements",
    patterns: [/\/lib\/db\/repository\/.+\.ts$/],
  },
  {
    name: "Tier 4: UI state management",
    target: 90,
    branchTarget: 75,
    metric: "statements",
    patterns: [/\/app\/answer\/.+\.(ts|tsx)$/],
  },
  {
    name: "Tier 5: UI components",
    target: 70,
    metric: "statements",
    patterns: [/\/components\/.+\.tsx$/],
  },
];

// ── Helpers ────────────────────────────────────────────────────────────

function loadCoverage(path) {
  if (!existsSync(path)) {
    console.error(`[coverage-check] Coverage report not found: ${path}`);
    console.error(`[coverage-check] Run 'pnpm exec vitest run --coverage' first.`);
    process.exit(2);
  }
  return JSON.parse(readFileSync(path, "utf-8"));
}

/** Compute aggregate coverage for a set of files. */
function aggregateCoverage(report, files, metric) {
  if (files.length === 0) return null;

  let totalCovered = 0;
  let total = 0;

  for (const file of files) {
    const data = report[file];
    if (!data) continue;
    totalCovered += data[metric]?.covered ?? 0;
    total += data[metric]?.total ?? 0;
  }

  if (total === 0) return null;
  return { pct: (totalCovered / total) * 100, covered: totalCovered, total };
}

function formatPct(value) {
  return `${value.toFixed(2)}%`;
}

// ── Main ───────────────────────────────────────────────────────────────

function main() {
  const jsonPath = process.env.COVERAGE_JSON || resolve(ROOT, "coverage/coverage-summary.json");

  const report = loadCoverage(jsonPath);

  /** All source file paths from the report. */
  const allFiles = Object.keys(report)
    .filter((f) => f.includes("/src/"))
    .filter((f) => !INTENTIONALLY_MOCKED.some((p) => p.test(f)));

  let allPass = true;
  const results = [];

  for (const tier of TIERS) {
    const matchedFiles = allFiles.filter((f) => tier.patterns.some((p) => p.test(f)));

    if (matchedFiles.length === 0) {
      allPass = false;
      results.push({
        tier: tier.name,
        stmts: "N/A",
        status: "❌ FAIL (No files matched)",
        pass: false,
      });
      continue;
    }

    const agg = aggregateCoverage(report, matchedFiles, tier.metric);
    if (!agg) {
      allPass = false;
      results.push({
        tier: tier.name,
        stmts: "N/A",
        status: "❌ FAIL (No coverage data)",
        pass: false,
      });
      continue;
    }

    const primaryPct = agg.pct;
    let pass = primaryPct >= tier.target;

    // Optional second gate (e.g. branches)
    let branchAgg = null;
    if (tier.branchTarget !== undefined) {
      branchAgg = aggregateCoverage(report, matchedFiles, "branches");
      if (!branchAgg || branchAgg.pct < tier.branchTarget) {
        pass = false;
      }
    }

    if (!pass) allPass = false;

    let detail = `(${agg.covered}/${agg.total} ${tier.metric})`;
    if (branchAgg && tier.branchTarget !== undefined) {
      detail += ` | branches: ${branchAgg.pct.toFixed(2)}% (target ${tier.branchTarget}%)`;
    }

    results.push({
      tier: tier.name,
      stmts: formatPct(primaryPct),
      target: `${tier.target}%`,
      status: pass ? "✅ PASS" : "❌ FAIL",
      pass,
      detail,
    });
  }

  // ── Output ────────────────────────────────────────────────────────────
  console.log("");
  console.log("📊 Coverage Tier Validation");
  console.log("=".repeat(60));

  for (const r of results) {
    const line = [
      r.tier.padEnd(30),
      (r.stmts || "").padStart(8),
      r.target ? `  target: ${r.target}`.padEnd(12) : " ".padEnd(12),
      r.status || "",
      r.detail || "",
    ].join("");
    console.log(line);
  }

  console.log("=".repeat(60));

  if (allPass) {
    console.log("✅ All tiers meet coverage targets.\n");
    process.exit(0);
  } else {
    console.log("❌ Some tiers are below coverage targets (blocking).\n");
    process.exit(1);
  }
}

main();
